import { dateLabel, today, daysUntil, calendarEvents, escapeHTML as h } from "./core.js";
import { applicationChecklist } from "./application-views.js";
import { missionSummary, missionStatus, MISSION_STATUSES } from "./mission-model.js";
import { icon } from "./icons.js";

export function homePage({ state, btn, missionFilter = "All", missionPhaseFilter = "All" }) {
  const summary = missionSummary(state.tasks);
  const apps = state.applications.filter(a => !a.archived);
  const upcoming = calendarEvents(state).filter(e => daysUntil(e.date) >= 0).slice(0, 4);
  const firstName = (state.profile.name || "").trim().split(/\s+/)[0];
  const ring = (percent, label) => `<span class="mission-ring" style="--progress:${percent}" role="img" aria-label="${h(label)} ${percent}%"><span>${percent}<small>%</small></span></span>`;
  const taskCard = task => {
    const status = missionStatus(task), app = apps.find(a => a.id === task.applicationId);
    return `<article class="mission-task ${status === "Done" ? "is-done" : ""}"><div class="mission-task-top"><button class="task-check ${status === "Done" ? "checked" : ""}" data-action="complete-task:${h(task.id)}" aria-label="${status === "Done" ? "Reopen" : "Complete"} ${h(task.title)}" aria-pressed="${status === "Done"}">${status === "Done" ? icon("check") : ""}</button><button class="mission-task-title" data-action="edit-task:${h(task.id)}">${h(task.title)}</button></div><p>${h(app?.name || task.category || "Personal plan")}</p><div class="mission-task-footer"><span class="mission-status status-${status === "In Progress" ? "progress" : status === "Done" ? "done" : status === "Waiting" ? "waiting" : "todo"}"><i></i>${h(status === "In Progress" ? "In progress" : status)}</span>${task.due ? `<span class="${daysUntil(task.due) < 0 && status !== "Done" ? "overdue-text" : ""}">${task.due === today() ? "Today" : dateLabel(task.due)}</span>` : ""}</div></article>`;
  };
  return `<div class="mission-view-bar"><div class="mission-views" aria-label="Plan views"><span class="selected">${icon("tasks")} Overview</span><button data-action="mission-board">${icon("compare")} Board view</button><a href="#planner">${icon("calendar")} Calendar view</a><a href="#focus">${icon("clock")} Focus view</a></div><span class="mission-date">${new Date().toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}</span></div>
  <section class="mission-overview" aria-labelledby="mission-status-title"><div class="mission-section-top"><h2 id="mission-status-title">By status</h2><span>${summary.done} of ${summary.total} tasks complete</span></div><div class="mission-status-bars">${MISSION_STATUSES.map((status, i) => `<button class="mission-status-row" data-action="mission-filter:${status}" aria-label="Show ${status} tasks"><span><i class="status-square status-${["todo", "progress", "done", "waiting"][i]}"></i>${status === "In Progress" ? "In progress" : status}</span><span class="mission-bar"><i class="status-${["todo", "progress", "done", "waiting"][i]}" style="width:${summary.total ? summary.counts[status] / summary.total * 100 : 0}%"></i></span><span>${summary.counts[status]}</span></button>`).join("")}</div></section>
  <section class="mission-phases" aria-label="Focus areas">${summary.phases.map(phase => `<button class="mission-phase ${missionPhaseFilter === phase.id ? "active" : ""}" data-action="mission-phase:${phase.id}" aria-pressed="${missionPhaseFilter === phase.id}"><span class="mission-phase-heading"><span class="mission-phase-icon">${icon(phase.icon)}</span><strong>${h(phase.title)}</strong></span><span class="mission-phase-body">${ring(phase.percent, phase.title)}<span class="mission-phase-count"><strong>${phase.done}<span>/${phase.items.length}</span></strong><small>tasks done</small></span></span><span class="mission-phase-caption">${phase.items.length ? `${phase.items.length - phase.done} remaining` : "Ready for your first task"}</span><span class="mission-bar"><i style="width:${phase.percent}%"></i></span></button>`).join("")}</section>
  <section class="mission-plan" aria-labelledby="mission-plan-heading"><div class="mission-section-top"><div><h2 id="mission-plan-heading">Your plan<span class="mission-total">${summary.total} tasks · 5 focus areas</span></h2><p>${firstName ? `${h(firstName)}, keep` : "Keep"} your next steps in sight. Open a task to review or edit it.</p></div>${btn("Add task", "add-task", "secondary", "plus")}</div><div class="mission-filters" aria-label="Filter plan tasks">${["All", "In Progress", "Waiting", "To do", "Done"].map(status => `<button data-action="mission-filter:${status}" class="${missionFilter === status ? "selected" : ""}" aria-pressed="${missionFilter === status}">${status === "Done" ? "Completed" : status === "In Progress" ? "In progress" : status}<span>${status === "All" ? summary.total : summary.counts[status]}</span></button>`).join("")}${missionPhaseFilter !== "All" ? `<button class="clear-phase" data-action="mission-phase:All">${icon("x")} All focus areas</button>` : ""}</div>
  ${summary.total ? summary.phases.filter(phase => missionPhaseFilter === "All" || phase.id === missionPhaseFilter).map(phase => {
    const items = phase.items.filter(t => missionFilter === "All" || missionStatus(t) === missionFilter).sort((a, b) => (missionStatus(a) === "Done") - (missionStatus(b) === "Done") || (a.due || "9999").localeCompare(b.due || "9999"));
    if (!items.length) return "";
    return `<section class="mission-group"><div class="mission-group-heading"><h3><span class="mission-group-icon">${icon(phase.icon)}</span>${h(phase.title)}</h3><a href="#${phase.route}">Open workspace ${icon("arrow")}</a><span>${phase.done} of ${phase.items.length} done</span></div><div class="mission-task-grid">${items.slice(0, 6).map(taskCard).join("")}</div>${items.length > 6 ? `<a class="mission-show-more" href="#tasks">View all ${items.length} tasks ${icon("arrow")}</a>` : ""}</section>`;
  }).join("") || `<div class="mission-empty">${icon("check")}<h3>No tasks in this view</h3><p>Choose another filter to see the rest of your plan.</p></div>` : `<div class="mission-empty">${icon("tasks")}<h3>Give your next steps a home</h3><p>Add tasks for your applications, schoolwork, and everyday plans.</p>${btn("Create your first task", "add-task", "primary", "plus")}</div>`}</section>
  <div class="mission-bottom-grid"><section class="mission-overview"><div class="mission-section-top"><h2>Application progress</h2><a href="#applications">View all ${icon("arrow")}</a></div>${apps.length ? apps.slice(0, 4).map(app => { const checklist = applicationChecklist(app); return `<a class="mission-app" href="#application/${h(app.id)}"><span class="mission-app-initial">${h(app.name.trim().charAt(0))}</span><div><strong>${h(app.name)}</strong><small>${h(app.status)} · ${checklist.done}/${checklist.total} required items</small><span class="mission-bar"><i style="width:${checklist.percent}%"></i></span></div><span>${checklist.percent}%</span>${icon("arrow")}</a>`; }).join("") : `<p class="mission-muted">Add a college to start your application checklists.</p><a class="text-link" href="#colleges">Explore colleges ${icon("arrow")}</a>`}</section><section class="mission-overview"><div class="mission-section-top"><h2>Coming up</h2><a href="#planner">Planner ${icon("arrow")}</a></div>${upcoming.length ? upcoming.map(event => `<a class="mission-upcoming" href="#${h(event.target)}"><span class="mission-date-tile"><small>${new Date(event.date + "T12:00:00").toLocaleDateString(undefined, {month:"short"})}</small><strong>${Number(event.date.slice(8))}</strong></span><div><strong>${h(event.title)}</strong><small>${h(event.kind)}${event.time ? ` · ${h(event.time)}` : ""}</small></div>${icon("arrow")}</a>`).join("") : `<p class="mission-muted">Your next deadlines and personal events will appear here.</p><a class="text-link" href="#planner">Plan your day ${icon("arrow")}</a>`}</section></div>`;
}
